import unittest
from candidate import fruit_distribution

class TestFruitDistribution(unittest.TestCase):
    def test_normal_case(self):
        self.assertEqual(fruit_distribution("5 apples and 6 oranges", 19), 8)

    def test_zero_apples_and_one_orange(self):
        self.assertEqual(fruit_distribution("0 apples and 1 oranges", 3), 2)

    def test_large_numbers(self):
        self.assertEqual(fruit_distribution("100 apples and 1 oranges", 120), 19)

    def test_sum_of_multiple_numbers(self):
        self.assertEqual(fruit_distribution("2 apples and 3 oranges and 4", 20), 11)

    def test_leading_and_trailing_spaces(self):
        self.assertEqual(fruit_distribution("   7 apples and 8 oranges   ", 25), 10)

    def test_no_digits_in_string(self):
        self.assertEqual(fruit_distribution("apples and oranges", 10), 10)

    def test_empty_string(self):
        self.assertEqual(fruit_distribution("", 5), 5)

    def test_string_with_non_digit_words_containing_numbers(self):
        self.assertEqual(fruit_distribution("12apples and 7 oranges", 30), 11)

    def test_string_with_decimal_numbers(self):
        self.assertEqual(fruit_distribution("3.5 apples and 2.5 oranges", 10), 10)

    def test_string_with_leading_zeros(self):
        self.assertEqual(fruit_distribution("005 apples and 06 oranges", 20), 9)

    def test_negative_n_value(self):
        self.assertEqual(fruit_distribution("5 apples and 3 oranges", -5), -13)

    def test_n_less_than_sum_of_apples_and_oranges(self):
        self.assertEqual(fruit_distribution("10 apples and 5 oranges", 12), -3)

    def test_large_integer_values(self):
        self.assertEqual(fruit_distribution("999999999 apples and 1 oranges", 1000000000), 0)

    def test_float_n_value(self):
        self.assertAlmostEqual(fruit_distribution("2 apples and 3 oranges", 10.5), 5.5)

    def test_string_is_none_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            fruit_distribution(None, 10)

    def test_integer_as_string_argument_raises_attribute_error(self):
        with self.assertRaises(AttributeError):
            fruit_distribution(123, 10)

    def test_non_numeric_n_raises_type_error(self):
        with self.assertRaises(TypeError):
            fruit_distribution("5 apples and 6 oranges", "twenty")

    def test_n_is_none_raises_type_error(self):
        with self.assertRaises(TypeError):
            fruit_distribution("5 apples and 6 oranges", None)

    def test_string_with_multiple_spaces_between_words(self):
        self.assertEqual(fruit_distribution("5   apples    and    6 oranges", 19), 8)

    def test_string_with_numbers_in_word_punctuations(self):
        self.assertEqual(fruit_distribution("5-apples-and-6-oranges", 20), 20)

    def test_string_with_negative_numbers_not_parsed(self):
        self.assertEqual(fruit_distribution("-5 apples and -6 oranges", 20), 20)

    def test_string_with_unicode_digits(self):
        self.assertEqual(fruit_distribution("５ apples and ６ oranges", 20), 20)

    def test_n_is_boolean_value(self):
        self.assertEqual(fruit_distribution("2 apples and 3 oranges", True), -4)

if __name__ == "__main__":
    unittest.main()
